-- Separate the original PC notebook without overwriting editor changes.
do $migration$
declare
  old_pc jsonb := convert_from(decode('', 'base64'), 'UTF8')::jsonb;
  new_pc jsonb := convert_from(decode('', 'base64'), 'UTF8')::jsonb;
  new_os jsonb := convert_from(decode('', 'base64'), 'UTF8')::jsonb;
  existing_config jsonb;
  os_node_id uuid;
begin
  select config into existing_config from public.guided_notebooks where slug = 'dentro-il-pc' for update;
  if not found then
    raise exception 'Il percorso dentro-il-pc non esiste: verificare la migrazione 0012.';
  end if;
  if existing_config = old_pc then
    update public.guided_notebooks
    set config = new_pc,
        description = case when description = 'Esplora in modo guidato come software e sistema operativo usano kernel, driver e componenti hardware come CPU, RAM e SSD, distinguendo il percorso dei dati da quello dell''alimentazione.' then 'Esplora i componenti fisici del computer: scheda madre, CPU, RAM, SSD, GPU, alimentazione e periferiche.' else description end
    where slug = 'dentro-il-pc';
  elsif existing_config <> new_pc then
    raise exception 'Il percorso dentro-il-pc ? stato modificato: confrontare e aggiornare manualmente prima di applicare la migrazione 0013.';
  end if;

  select config into existing_config from public.guided_notebooks where slug = 'sistema-operativo' for update;
  if found then
    if existing_config <> new_os then
      raise exception 'Esiste gi? un percorso sistema-operativo diverso: confrontare i contenuti prima di applicare la migrazione 0013.';
    end if;
  else
    select n.id into os_node_id from public.nodes n
    where n.slug = 'sistema-operativo'
      and not exists (select 1 from public.guided_notebooks g where g.node_id = n.id);
    insert into public.guided_notebooks (slug, description, node_id, pending_node_slug, config)
    values ('sistema-operativo', 'Scopri come applicazioni, sistema operativo, kernel e driver collaborano per usare le risorse e i dispositivi del computer.', os_node_id,
      case when os_node_id is null then 'sistema-operativo' else null end, new_os);
  end if;
end;
$migration$;
